<?php $title='Comments';require __DIR__.'/_layout.php';if(!can_manage('comments'))exit('Forbidden');if(isset($_GET['action'],$_GET['id'])){ $id=(int)$_GET['id'];$a=$_GET['action'];if(in_array($a,['approved','rejected','spam'],true))db()->prepare("UPDATE comments SET status=? WHERE id=?")->execute([$a,$id]);elseif($a==='delete')db()->prepare("DELETE FROM comments WHERE id=?")->execute([$id]);redirect('comments.php');}$rows=db()->query("SELECT c.*,p.title FROM comments c JOIN posts p ON p.id=c.post_id ORDER BY c.created_at DESC")->fetchAll();?><h1>Comments</h1><table class="table"><tr><th>Post</th><th>Name</th><th>Comment</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['name'])?></td><td><?=e(mb_strimwidth($r['comment'],0,100,'…'))?></td><td><?=e($r['status'])?></td><td><a href="?action=approved&id=<?=$r['id']?>">Approve</a> · <a href="?action=rejected&id=<?=$r['id']?>">Reject</a> · <a data-confirm="Delete?" href="?action=delete&id=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table><?php require __DIR__.'/_footer.php';?>